return {
  apply(ctx) {
    const shell = ctx.get('shell')
    const fs = ctx.get('fs')
    const sandboxPolicy = ctx.get('sandboxPolicy')
    if (shell === undefined || fs === undefined || sandboxPolicy === undefined) return

    const ROOT = 'C:\\Users\\Administrator\\project\\deepseek-workspace'
    const TOOLS = ROOT + '\\.dsh-tools'
    const GH_API = TOOLS + '\\gh_api.py'
    const CFG_FILE = TOOLS + '\\gh-config.json'
    const PYTHON = 'C:\\Users\\Administrator\\AppData\\Local\\Programs\\Python\\Python311\\python.exe'
    const REPO = 'fantasy-mark/gh_repo'
    const BRANCH = 'main'
    const MAX_UPLOAD = 200 * 1024
    const WORKFLOW_FILE = '.github/workflows/url-download.yml'
    const BOOKMARKS_FILE = ROOT + '\\.dsh-bookmarks.json'
    const BOOKMARKS_REPO = 'bookmarks.json'

    const WORKSPACE_POLICY = { mode: 'workspace-write', workspaceRoot: ROOT }

    async function runPy(args, timeoutMs) {
      const spec = shell.resolve({
        command: '& ' + q(PYTHON) + ' ' + q(GH_API) + ' ' + args,
        workdir: ROOT,
        timeoutMs: timeoutMs || 120000,
        stdoutMaxBytes: 32 * 1024 * 1024,
        sandboxPolicy: WORKSPACE_POLICY,
      })
      const res = await shell.run(spec)
      if (res.sandbox && res.sandbox.denied) throw new Error('命令被沙箱拒绝')
      if (res.exitCode !== 0) {
        throw new Error('gh_api 失败 (exit ' + res.exitCode + '): ' + String(res.stderr && res.stderr.text || '').slice(0, 400))
      }
      try {
        return JSON.parse(String(res.stdout && res.stdout.text || '').trim())
      } catch (e) {
        throw new Error('无法解析 gh_api 输出')
      }
    }

    function q(s) { return "'" + String(s).replace(/'/g, "''") + "'" }

    function escArg(s) {
      return "'" + String(s).replace(/'/g, "''") + "'"
    }

    // body 用 base64 传参，避免命令行引号问题，也不需要临时文件/目录
    function bodyB64Arg(obj) {
      const b64 = Buffer.from(JSON.stringify(obj), 'utf8').toString('base64')
      return ' --body-b64 ' + q(b64)
    }

    async function readConfig() {
      try {
        const target = await fs.resolve(CFG_FILE, { cwd: ROOT })
        const info = await fs.stat(target)
        if (!info) return null
        const text = await fs.readText(target)
        const d = JSON.parse(text)
        return (d && d.pat) ? d : null
      } catch (e) {
        return null
      }
    }

    async function writeConfig(pat) {
      const target = await fs.resolve(CFG_FILE, { cwd: ROOT })
      await fs.writeText(target, JSON.stringify({ pat, repo: REPO, branch: BRANCH }, null, 2), undefined, undefined, WORKSPACE_POLICY)
    }

    async function clearConfig() {
      try {
        const target = await fs.resolve(CFG_FILE, { cwd: ROOT })
        const info = await fs.stat(target)
        if (info) {
          await fs.writeText(target, '', undefined, undefined, WORKSPACE_POLICY)
        }
      } catch (e) { /* ignore */ }
    }

    async function verifyPat(pat) {
      const r = await runPy('GET /user --pat ' + escArg(pat), 30000)
      if (r.status === 200 && r.json && r.json.login) return r.json.login
      return null
    }

    async function repoPrivate(pat) {
      const r = await runPy('GET /repos/' + REPO + ' --pat ' + escArg(pat), 30000)
      if (r.status === 200 && r.json) return r.json.private === true
      return false
    }

    // workflow v11：调用仓库内 .github/scripts/bili_dl.py 下载 B 站视频
    const WORKFLOW_YAML = [
      'name: url-download',
      'on:',
      '  workflow_dispatch:',
      '    inputs:',
      '      url:',
      "        description: 'URL to download'",
      '        required: true',
      'permissions:',
      '  contents: write',
      'jobs:',
      '  download:',
      '    runs-on: ubuntu-latest',
      '    steps:',
      '      - name: Checkout',
      '        uses: actions/checkout@v4',
      '      - name: Download',
      '        env:',
      '          GH_TOKEN: ${{ github.token }}',
      '          URL: ${{ github.event.inputs.url }}',
      '        run: |',
      '          set -e',
      '          URL="$URL"',
      '          if [[ "$URL" == *"bilibili.com/video/"* ]]; then',
      '            echo "Bilibili video detected, resolving stream..."',
      '            python3 .github/scripts/bili_dl.py',
      '          elif [[ "$URL" == *"raw.githubusercontent.com"* || "$URL" == *"api.github.com"* ]]; then',
      '            if [[ "$URL" == *"/contents/"* ]]; then',
      '              gh api "$URL" -H "Accept: application/vnd.github.raw" > artifact.bin',
      '            else',
      '              curl -fL --retry 3 -H "Authorization: Bearer $GH_TOKEN" -o artifact.bin "$URL"',
      '            fi',
      '          else',
      '            curl -fL --retry 3 -o artifact.bin "$URL"',
      '            BN="$(basename "$URL" | sed \'s/?.*//\')"',
      '            if [[ -n "$BN" && "$BN" != "artifact.bin" && "$BN" != *".html" ]]; then',
      '              cp artifact.bin "$BN"',
      '              echo "$BN" > .outname',
      '            fi',
      '          fi',
      '      - name: Create release and upload',
      '        env:',
      '          GH_TOKEN: ${{ github.token }}',
      '        run: |',
      '          TAG="download-$(date +%s)"',
      '          if [[ -f .outname ]]; then',
      '            OUT="$(cat .outname)"',
      '          else',
      '            OUT="artifact.bin"',
      '          fi',
      '          echo "uploading: $OUT"',
      '          gh release create "$TAG" "$OUT" --repo "$GITHUB_REPOSITORY" --title "Download $(date -u +%Y%m%d-%H%M%S)" --generate-notes || true',
      '',
    ].join('\n')

    async function ensureWorkflow(pat) {
      const path = WORKFLOW_FILE.replace(/^\//, '')
      const r = await runPy('GET /repos/' + REPO + '/contents/' + path + ' --pat ' + escArg(pat), 30000)
      if (r.status === 200) return true
      const b64 = Buffer.from(WORKFLOW_YAML, 'utf8').toString('base64')
      const arg = bodyB64Arg({ message: 'add url-download workflow', content: b64 })
      const put = await runPy('PUT /repos/' + REPO + '/contents/' + path + ' --pat ' + escArg(pat) + arg, 30000)
      return put.status === 200 || put.status === 201
    }

    // 书签备份：本地 .dsh-bookmarks.json → 仓库 bookmarks.json
    async function backupBookmarksToRepo(pat) {
      const target = await fs.resolve(BOOKMARKS_FILE, { cwd: ROOT })
      const info = await fs.stat(target)
      if (!info) return { ok: false, error: '本地书签文件不存在（请先在书签标签添加书签）' }
      const text = await fs.readText(target)
      const bytes = Buffer.byteLength(text, 'utf8')
      if (bytes > MAX_UPLOAD) return { ok: false, error: '书签文件超过 200KB 限制（' + Math.round(bytes / 1024) + ' KB）' }
      const b64 = Buffer.from(text, 'utf8').toString('base64')
      const existing = await runPy('GET /repos/' + REPO + '/contents/' + BOOKMARKS_REPO + ' --pat ' + escArg(pat), 30000)
      const body = { message: 'backup bookmarks via dsh', content: b64 }
      if (existing.status === 200 && existing.json && existing.json.sha) {
        body.sha = existing.json.sha
      }
      const r = await runPy('PUT /repos/' + REPO + '/contents/' + BOOKMARKS_REPO + ' --pat ' + escArg(pat) + bodyB64Arg(body), 60000)
      if (r.status === 200 || r.status === 201) return { ok: true, path: BOOKMARKS_REPO, bytes }
      return { ok: false, error: (r.error && r.error.message) || ('备份失败 ' + r.status) }
    }

    // 书签恢复：仓库 bookmarks.json → 本地 .dsh-bookmarks.json
    async function restoreBookmarksFromRepo(pat) {
      const r = await runPy('GET /repos/' + REPO + '/contents/' + BOOKMARKS_REPO + ' --pat ' + escArg(pat), 30000)
      if (r.status !== 200 || !r.json || !r.json.content) {
        return { ok: false, error: (r.error && r.error.message) || '仓库中没有 bookmarks.json' }
      }
      const text = Buffer.from(r.json.content, 'base64').toString('utf8')
      const target = await fs.resolve(BOOKMARKS_FILE, { cwd: ROOT })
      await fs.writeText(target, text, undefined, undefined, WORKSPACE_POLICY)
      return { ok: true, bytes: Buffer.byteLength(text, 'utf8') }
    }

    harness.handle('gh.config', async () => {
      const cfg = await readConfig()
      if (!cfg) return { ok: true, patSet: false, repo: REPO, defaultBranch: BRANCH, private: false }
      const isPrivate = await repoPrivate(cfg.pat)
      return { ok: true, patSet: true, repo: REPO, defaultBranch: BRANCH, private: isPrivate }
    })

    harness.handle('gh.setPat', async (args) => {
      const pat = args && args.pat ? String(args.pat).trim() : ''
      if (!pat) return { ok: false, error: 'PAT 不能为空' }
      const login = await verifyPat(pat)
      if (!login) return { ok: false, error: 'PAT 无效：无法通过 GitHub 验证' }
      await writeConfig(pat)
      const isPrivate = await repoPrivate(pat)
      return { ok: true, repo: REPO, login, private: isPrivate }
    })

    harness.handle('gh.clearPat', async () => {
      await clearConfig()
      return { ok: true }
    })

    harness.handle('gh.list', async (args) => {
      const cfg = await readConfig()
      if (!cfg) return { ok: false, error: '未设置 PAT' }
      const p = args && args.path ? String(args.path).replace(/^\/+|\/+$/g, '') : ''
      const apiPath = '/repos/' + REPO + '/contents' + (p ? '/' + p : '')
      const r = await runPy('GET ' + apiPath + ' --pat ' + escArg(cfg.pat), 30000)
      if (r.status !== 200) {
        return { ok: false, error: (r.error && r.error.message) || ('GitHub 返回 ' + r.status) }
      }
      const arr = Array.isArray(r.json) ? r.json : []
      const items = arr.map((it) => ({
        name: it.name || '',
        path: it.path || '',
        type: it.type === 'dir' ? 'dir' : 'file',
        size: it.size != null ? it.size : null,
        sha: it.sha || '',
      }))
      return { ok: true, items }
    })

    harness.handle('gh.getFile', async (args) => {
      const cfg = await readConfig()
      if (!cfg) return { ok: false, error: '未设置 PAT' }
      const p = String((args && args.path) || '').replace(/^\/+/, '')
      const r = await runPy('GET /repos/' + REPO + '/contents/' + p + ' --pat ' + escArg(cfg.pat), 30000)
      if (r.status !== 200 || !r.json) {
        return { ok: false, error: (r.error && r.error.message) || ('下载失败 ' + r.status) }
      }
      if (r.json.content) {
        return { ok: true, name: r.json.name || p.split('/').pop(), content: r.json.content }
      }
      if (r.json.download_url) {
        return { ok: true, name: r.json.name || p.split('/').pop(), downloadUrl: r.json.download_url }
      }
      return { ok: false, error: '文件内容不可用' }
    })

    harness.handle('gh.putFile', async (args) => {
      const cfg = await readConfig()
      if (!cfg) return { ok: false, error: '未设置 PAT' }
      const p = String((args && args.path) || '').replace(/^\/+/, '')
      const content = String((args && args.content) || '')
      if (!p) return { ok: false, error: '路径不能为空' }
      try {
        const bytes = Buffer.from(content, 'base64')
        if (bytes.length > MAX_UPLOAD) {
          return { ok: false, error: '文件超过 200KB 限制（' + Math.round(bytes.length / 1024) + ' KB）' }
        }
        const r = await runPy('PUT /repos/' + REPO + '/contents/' + p + ' --pat ' + escArg(cfg.pat) + bodyB64Arg({ message: 'upload via dsh gh tab', content }), 60000)
        if (r.status === 200 || r.status === 201) return { ok: true }
        return { ok: false, error: (r.error && r.error.message) || ('上传失败 ' + r.status) }
      } catch (e) {
        return { ok: false, error: String(e) }
      }
    })

    harness.handle('gh.delFile', async (args) => {
      const cfg = await readConfig()
      if (!cfg) return { ok: false, error: '未设置 PAT' }
      const p = String((args && args.path) || '').replace(/^\/+/, '')
      const sha = String((args && args.sha) || '')
      if (!p || !sha) return { ok: false, error: '缺少路径或 sha' }
      const r = await runPy('DELETE /repos/' + REPO + '/contents/' + p + ' --pat ' + escArg(cfg.pat) + bodyB64Arg({ message: 'delete via dsh gh tab', sha }), 30000)
      if (r.status === 200) return { ok: true }
      return { ok: false, error: (r.error && r.error.message) || ('删除失败 ' + r.status) }
    })

    harness.handle('gh.downloadStart', async (args) => {
      const cfg = await readConfig()
      if (!cfg) return { ok: false, error: '未设置 PAT' }
      const url = args && args.url ? String(args.url).trim() : ''
      if (!url) return { ok: false, error: 'URL 不能为空' }
      const okWf = await ensureWorkflow(cfg.pat)
      if (!okWf) return { ok: false, error: '无法创建/确认 workflow 文件' }
      const r = await runPy('POST /repos/' + REPO + '/actions/workflows/url-download.yml/dispatches --pat ' + escArg(cfg.pat) + bodyB64Arg({ ref: BRANCH, inputs: { url } }), 30000)
      if (r.status === 204) return { ok: true }
      return { ok: false, error: (r.error && r.error.message) || ('触发 Action 失败 ' + r.status) }
    })

    harness.handle('gh.downloadStatus', async () => {
      const cfg = await readConfig()
      if (!cfg) return { ok: false, error: '未设置 PAT' }
      const runs = await runPy('GET /repos/' + REPO + '/actions/workflows/url-download.yml/runs --pat ' + escArg(cfg.pat) + ' --field per_page=1 --field page=1', 30000)
      if (runs.status !== 200 || !runs.json || !runs.json.workflow_runs || runs.json.workflow_runs.length === 0) {
        return { ok: false, error: '没有找到 workflow run' }
      }
      const run = runs.json.workflow_runs[0]
      if (run.status === 'completed') {
        const rel = await runPy('GET /repos/' + REPO + '/releases --pat ' + escArg(cfg.pat) + ' --field per_page=1', 30000)
        if (rel.status === 200 && rel.json && rel.json.length > 0) {
          const latest = rel.json[0]
          const asset = latest.assets && latest.assets[0]
          if (asset) {
            return { ok: true, finished: true, status: 'completed', assetUrl: asset.browser_download_url, assetName: asset.name, releaseTag: latest.tag_name }
          }
          return { ok: true, finished: true, status: 'completed', assetUrl: latest.html_url, assetName: latest.name, releaseTag: latest.tag_name }
        }
        return { ok: true, finished: true, status: 'completed', assetUrl: '', assetName: '' }
      }
      const conclusion = run.conclusion || 'running'
      return { ok: true, finished: false, status: conclusion === 'running' ? (run.status === 'in_progress' ? '运行中…' : '排队中…') : conclusion }
    })

    harness.handle('gh.backupBookmarks', async () => {
      const cfg = await readConfig()
      if (!cfg) return { ok: false, error: '未设置 PAT' }
      return backupBookmarksToRepo(cfg.pat)
    })

    harness.handle('gh.restoreBookmarks', async () => {
      const cfg = await readConfig()
      if (!cfg) return { ok: false, error: '未设置 PAT' }
      return restoreBookmarksFromRepo(cfg.pat)
    })

    harness.handle('gh.repoInfo', async () => {
      const cfg = await readConfig()
      if (!cfg) return { ok: true, repo: REPO, defaultBranch: BRANCH }
      const isPrivate = await repoPrivate(cfg.pat)
      return { ok: true, repo: REPO, defaultBranch: BRANCH, private: isPrivate }
    })
  },
}

