return {
  inject: ['timer'],
  apply(ctx) {
    const slots = ctx.get('slots')
    if (slots === undefined) return

    styles.insert(`
      .dsw-gh-root { height: 100%; overflow-y: auto; padding: 16px 20px 40px; box-sizing: border-box; color: var(--dsw-alias-label-primary); background: var(--dsw-alias-bg-base); font-size: 14px; line-height: 1.6; }
      .dsw-gh-header { display: flex; align-items: baseline; gap: 10px; margin-bottom: 12px; }
      .dsw-gh-title-lg { font-size: 18px; font-weight: 600; }
      .dsw-gh-desc { font-size: 12px; color: var(--dsw-alias-label-secondary); }
