      .dsw-gh-btn:hover { border-color: var(--dsw-alias-border-l2); }
      .dsw-gh-btn-primary { background: var(--dsw-alias-brand-primary); color: #fff; border-color: transparent; }
      .dsw-gh-btn-primary:disabled { opacity: 0.6; cursor: not-allowed; }
      .dsw-gh-btn-sm { padding: 4px 10px; font-size: 12px; }
      .dsw-gh-btn-disabled { opacity: 0.45; cursor: not-allowed; pointer-events: none; color: var(--dsw-alias-label-secondary); }
      .dsw-gh-row { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
      .dsw-gh-error { color: var(--dsw-alias-state-error-primary); font-size: 13px; margin: 6px 0; }
      .dsw-gh-ok { color: var(--dsw-alias-state-success-primary); font-size: 13px; margin: 6px 0; }
