      .dsw-gh-item { display: flex; align-items: center; gap: 10px; padding: 7px 8px; border-bottom: 1px solid var(--dsw-alias-border-l1); font-size: 13px; }
      .dsw-gh-item:last-child { border-bottom: none; }
      .dsw-gh-item-name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; cursor: pointer; }
      .dsw-gh-item-name:hover { color: var(--dsw-alias-brand-primary); }
      .dsw-gh-item-meta { color: var(--dsw-alias-label-secondary); font-size: 12px; }
      .dsw-gh-status { margin: 6px 0; padding: 8px 12px; border: 1px solid var(--dsw-alias-border-l1); border-radius: 6px; font-size: 13px; background: var(--dsw-alias-bg-layer-1); }
      .dsw-gh-progress { margin-top: 6px; height: 4px; border-radius: 2px; background: var(--dsw-alias-border-l1); overflow: hidden; }
