      .dsw-gh-hint { font-size: 12px; color: var(--dsw-alias-label-secondary); margin-top: 6px; }
    `)

    var B64_CHARS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
    function bytesToBase64(u8) {
      var out = ''
      var i = 0
      for (; i + 2 < u8.length; i += 3) {
        var n = (u8[i] << 16) | (u8[i + 1] << 8) | u8[i + 2]
        out += B64_CHARS[(n >> 18) & 63] + B64_CHARS[(n >> 12) & 63] + B64_CHARS[(n >> 6) & 63] + B64_CHARS[n & 63]
      }
      var rem = u8.length - i
      if (rem === 1) {
        var n1 = u8[i] << 16
        out += B64_CHARS[(n1 >> 18) & 63] + B64_CHARS[(n1 >> 12) & 63] + '=='
      } else if (rem === 2) {
        var n2 = (u8[i] << 16) | (u8[i + 1] << 8)
        out += B64_CHARS[(n2 >> 18) & 63] + B64_CHARS[(n2 >> 12) & 63] + B64_CHARS[(n2 >> 6) & 63] + '='
      }
      return out
    }

    function GhView() {
      const h = React.createElement
      const [cfg, setCfg] = React.useState(null)
      const [pat, setPat] = React.useState('')
      const [patBusy, setPatBusy] = React.useState(false)
      const [msg, setMsg] = React.useState(null)

      const [path, setPath] = React.useState('')
      const [items, setItems] = React.useState(null)
      const [fsMsg, setFsMsg] = React.useState(null)

      const [dlUrl, setDlUrl] = React.useState('')
      const [dlState, setDlState] = React.useState(null)
      const [dlResult, setDlResult] = React.useState(null)

      const [bkMsg, setBkMsg] = React.useState(null)
      const [bkBusy, setBkBusy] = React.useState(false)

      React.useEffect(() => {
        let alive = true
        host.call('gh.config').then((r) => {
          if (!alive) return
          setCfg(r || { patSet: false })
          if (r && r.patSet) refreshList('')
        }).catch(() => {})
        return () => { alive = false }
      }, [])

      const refreshList = (p, cb) => {
        host.call('gh.list', { path: p || '' }).then((r) => {
          setPath(p || '')
          if (r && r.ok) {
            const list = r.items || []
            const withUris = list.map((it) => {
              if (it.type !== 'file') return it
              const enriched = Object.assign({}, it, { dataUri: '', downloadUrl: '' })
              host.call('gh.getFile', { path: it.path }).then((gr) => {
                if (gr && gr.ok && gr.content) {
                  enriched.dataUri = 'data:application/octet-stream;base64,' + gr.content
                  setItems((prev) => (prev || []).map((x) => x.path === it.path ? enriched : x))
                } else if (gr && gr.ok && gr.downloadUrl) {
                  enriched.downloadUrl = gr.downloadUrl
                  setItems((prev) => (prev || []).map((x) => x.path === it.path ? enriched : x))
                }
              }).catch(() => {})
              return enriched
            })
            setItems(withUris)
          } else {
            setItems([]); setFsMsg({ err: (r && r.error) || '列表获取失败' })
          }
          if (cb) cb()
        }).catch((e) => { setItems([]); setFsMsg({ err: String(e) }); if (cb) cb() })
      }

      const savePat = () => {
        const p = pat.trim()
        if (!p) return
        setPatBusy(true); setMsg(null)
        host.call('gh.setPat', { pat: p }).then((r) => {
          setPatBusy(false)
          if (r && r.ok) {
            setCfg({ patSet: true, repo: r.repo, private: r.private })
            setPat('')
            setMsg({ ok: 'PAT 已保存并验证通过' })
            refreshList('')
          } else {
            setMsg({ err: (r && r.error) || 'PAT 无效或保存失败' })
          }
        }).catch((e) => { setPatBusy(false); setMsg({ err: String(e) }) })
      }

      const clearPat = () => {
        host.call('gh.clearPat').then((r) => {
          if (r && r.ok) { setCfg({ patSet: false }); setItems(null); setMsg(null); setFsMsg(null); setBkMsg(null) }
        }).catch(() => {})
      }

      const enterDir = (item) => { if (item.type === 'dir') refreshList(item.path) }

      const proxyUrlFor = (item) => {
        const branch = (cfg && cfg.defaultBranch) || 'main'
        const repo = (cfg && cfg.repo) || 'fantasy-mark/gh_repo'
        const raw = 'https://raw.githubusercontent.com/' + repo + '/' + branch + '/' + item.path
        return 'https://proxy.vvvv.ee/' + raw
      }

      const deleteFile = (item) => {
        setFsMsg(null)
        host.call('gh.delFile', { path: item.path, sha: item.sha }).then((r) => {
          if (r && r.ok) { setFsMsg({ ok: '已删除 ' + item.name }); refreshList(path) }
          else setFsMsg({ err: (r && r.error) || '删除失败' })
        }).catch((e) => { setFsMsg({ err: String(e) }) })
      }

      const onUpload = (ev) => {
        const file = ev.target.files && ev.target.files[0]
        if (!file) return
        if (file.size > 200 * 1024) {
          setFsMsg({ err: '文件超过 200KB 限制：' + file.name + ' (' + Math.round(file.size / 1024) + ' KB)' })
          ev.target.value = ''
          return
        }
        const promise = typeof file.arrayBuffer === 'function'
          ? file.arrayBuffer()
          : Promise.reject(new Error('arrayBuffer 不可用'))
        promise.then((buf) => {
          const bytes = new Uint8Array(buf)
          const b64 = bytesToBase64(bytes)
          host.call('gh.putFile', { path: (path ? path + '/' : '') + file.name, content: b64 }).then((r) => {
            if (r && r.ok) { setFsMsg({ ok: '已上传 ' + file.name }); refreshList(path) }
            else setFsMsg({ err: (r && r.error) || '上传失败' })
          }).catch((e) => { setFsMsg({ err: String(e) }) })
        }).catch((e) => { setFsMsg({ err: '读取文件失败: ' + String(e) }) })
        ev.target.value = ''
      }

      const startDownload = () => {
        const u = dlUrl.trim()
        if (!u || (dlState && !dlState.done && !dlState.error)) return
        setDlState({ stage: '触发 GitHub Action…' }); setDlResult(null)
        host.call('gh.downloadStart', { url: u }).then((r) => {
          if (!r || !r.ok) { setDlState({ stage: '失败', error: (r && r.error) || '触发失败' }); return }
          setDlState({ stage: 'Action 已触发，等待完成…' })
        }).catch((e) => { setDlState({ stage: '失败', error: String(e) }) })
      }

      React.useEffect(() => {
        if (!dlState || dlState.done || dlState.error) return undefined
        const disposer = ctx.interval(() => {
          host.call('gh.downloadStatus').then((r) => {
            if (r && r.ok && r.finished) {
              setDlState({ stage: '完成', done: true })
              setDlResult({ url: r.assetUrl, name: r.assetName })
            } else if (r && r.ok) {
              setDlState({ stage: r.status || '运行中…' })
            } else {
              setDlState({ stage: '失败', error: (r && r.error) || '查询失败' })
            }
          }).catch(() => {})
        }, 3000)
        return () => { if (disposer) disposer() }
      }, [dlState])

      const backupBookmarks = () => {
        setBkBusy(true); setBkMsg(null)
        host.call('gh.backupBookmarks').then((r) => {
          setBkBusy(false)
          if (r && r.ok) setBkMsg({ ok: '书签已备份到仓库：' + ((r && r.path) || 'bookmarks.json') + ' (' + ((r && r.bytes) || 0) + ' bytes)' })
          else setBkMsg({ err: (r && r.error) || '备份失败' })
        }).catch((e) => { setBkBusy(false); setBkMsg({ err: String(e) }) })
      }

      const restoreBookmarks = () => {
        setBkBusy(true); setBkMsg(null)
        host.call('gh.restoreBookmarks').then((r) => {
          setBkBusy(false)
          if (r && r.ok) setBkMsg({ ok: '已从仓库恢复书签（' + ((r && r.bytes) || 0) + ' bytes）→ 请切换到书签标签查看' })
          else setBkMsg({ err: (r && r.error) || '恢复失败' })
        }).catch((e) => { setBkBusy(false); setBkMsg({ err: String(e) }) })
      }

      const repoLabel = (cfg && cfg.repo) || 'fantasy-mark/gh_repo'
      const branch = (cfg && cfg.defaultBranch) || 'main'
      const isPrivate = !!(cfg && cfg.private)

      if (!cfg) return h('div', { className: 'dsw-gh-root' }, '加载中…')

      if (!cfg.patSet) {
        return h('div', { className: 'dsw-gh-root' },
          h('div', { className: 'dsw-gh-header' },
            h('div', { className: 'dsw-gh-title-lg' }, 'GitHub 工具箱'),
            h('div', { className: 'dsw-gh-desc' }, '管理 ' + repoLabel + ' 仓库文件，用 GitHub Action 下载任意 URL 并发布到 Release'),
          ),
          h('div', { className: 'dsw-gh-section' },
            h('div', { className: 'dsw-gh-section-title' }, '初始化：设置 Personal Access Token (PAT)'),
            h('div', { className: 'dsw-gh-hint' }, '需要一个有 ' + repoLabel + ' 仓库读写权限的 PAT：'),
            h('div', { className: 'dsw-gh-row' },
              h('a', { className: 'dsw-gh-link', href: 'https://github.com/settings/tokens?type=beta', target: '_blank', rel: 'noreferrer' }, '创建 Fine-grained PAT →'),
              h('a', { className: 'dsw-gh-link', href: 'https://github.com/settings/tokens', target: '_blank', rel: 'noreferrer' }, '或创建 classic PAT →'),
            ),
            h('div', { className: 'dsw-gh-hint' }, '权限要求：Contents(读写) + Actions(读写) + 仓库元数据读取。'),
            h('input', { className: 'dsw-gh-input', type: 'password', value: pat, onChange: (e) => setPat(e.target.value), placeholder: '粘贴 github_pat_xxx 或 ghp_xxx' }),
            h('div', { className: 'dsw-gh-row' },
              h('button', { className: 'dsw-gh-btn dsw-gh-btn-primary', onClick: savePat, disabled: patBusy }, patBusy ? '验证中…' : '保存并验证'),
            ),
            msg && msg.err ? h('div', { className: 'dsw-gh-error' }, msg.err) : null,
            msg && msg.ok ? h('div', { className: 'dsw-gh-ok' }, msg.ok) : null,
            h('div', { className: 'dsw-gh-hint' }, 'PAT 仅保存在本机工作区 .dsh-tools/gh-config.json，不会上传到任何服务器。'),
          ),
        )
      }

      return h('div', { className: 'dsw-gh-root' },
        h('div', { className: 'dsw-gh-header' },
          h('div', { className: 'dsw-gh-title-lg' }, 'GitHub 工具箱'),
          h('div', { className: 'dsw-gh-desc' }, repoLabel + ' · ' + branch + (isPrivate ? ' · 私有仓库' : '')),
          h('button', { className: 'dsw-gh-btn dsw-gh-btn-sm', onClick: clearPat }, '清除 PAT'),
        ),

        h('div', { className: 'dsw-gh-section' },
          h('div', { className: 'dsw-gh-section-title' }, '① URL 下载 → 自动发布 Release（支持 B 站视频）'),
          h('div', { className: 'dsw-gh-hint' }, '粘贴任意文件下载链接（含 B 站视频链接），插件触发仓库 GitHub Action 下载并发布到 Release。B 站视频自动解析为 {标题}.mp4（匿名 480p）。'),
          h('div', { className: 'dsw-gh-row' },
            h('input', { className: 'dsw-gh-input', style: { flex: 1, marginBottom: 0 }, value: dlUrl, onChange: (e) => setDlUrl(e.target.value), placeholder: 'https://www.bilibili.com/video/BV... 或任意文件 URL' }),
            h('button', { className: 'dsw-gh-btn dsw-gh-btn-primary', onClick: startDownload, disabled: !!(dlState && !dlState.done && !dlState.error) }, '开始下载'),
          ),
          dlState && dlState.stage ? h('div', { className: 'dsw-gh-status' }, dlState.stage) : null,
          dlState && dlState.error ? h('div', { className: 'dsw-gh-error' }, dlState.error) : null,
          dlResult ? h('div', { className: 'dsw-gh-ok' },
            h('div', null, '已发布：' + (dlResult.name || '')),
            h('div', null, h('a', { className: 'dsw-gh-link', href: dlResult.url, target: '_blank', rel: 'noreferrer' }, dlResult.url)),
          ) : null,
        ),

        h('div', { className: 'dsw-gh-section' },
          h('div', { className: 'dsw-gh-section-title' }, '② 书签备份（本地书签 ↔ 仓库）'),
          h('div', { className: 'dsw-gh-hint' }, '把书签标签的数据（.dsh-bookmarks.json）备份到仓库 bookmarks.json，或从仓库恢复到本地。'),
          h('div', { className: 'dsw-gh-row' },
            h('button', { className: 'dsw-gh-btn dsw-gh-btn-sm', onClick: backupBookmarks, disabled: bkBusy }, '备份书签到仓库'),
            h('button', { className: 'dsw-gh-btn dsw-gh-btn-sm', onClick: restoreBookmarks, disabled: bkBusy }, '从仓库恢复书签'),
          ),
          bkMsg && bkMsg.err ? h('div', { className: 'dsw-gh-error' }, bkMsg.err) : null,
          bkMsg && bkMsg.ok ? h('div', { className: 'dsw-gh-ok' }, bkMsg.ok) : null,
        ),

        h('div', { className: 'dsw-gh-section' },
          h('div', { className: 'dsw-gh-section-title' }, '③ 仓库文件管理（< 200KB 上传）'),
          h('div', { className: 'dsw-gh-row' },
            h('button', { className: 'dsw-gh-btn dsw-gh-btn-sm', onClick: () => refreshList(''), disabled: !path }, '← 返回根目录'),
            h('span', { className: 'dsw-gh-item-meta' }, '当前: /' + path),
            h('label', { className: 'dsw-gh-btn dsw-gh-btn-sm', style: { cursor: 'pointer' } },
              '上传文件',
              h('input', { type: 'file', style: { display: 'none' }, onChange: onUpload }),
            ),
          ),
          fsMsg && fsMsg.err ? h('div', { className: 'dsw-gh-error' }, fsMsg.err) : null,
          fsMsg && fsMsg.ok ? h('div', { className: 'dsw-gh-ok' }, fsMsg.ok) : null,
          !items
            ? h('div', { className: 'dsw-gh-hint' }, '加载中…')
            : items.length === 0
              ? h('div', { className: 'dsw-gh-hint' }, '（空目录）')
              : h('div', { className: 'dsw-gh-list' },
                  items.map((it) => {
                    const proxyUrl = it.type === 'file' ? proxyUrlFor(it) : ''
                    const dataHref = it.type === 'file' && it.dataUri ? it.dataUri : ''
                    const dlHref = it.type === 'file' && it.downloadUrl ? it.downloadUrl : dataHref
                    return h('div', { key: it.path, className: 'dsw-gh-item' },
                      h('span', { className: 'dsw-gh-item-name', onClick: () => it.type === 'dir' ? enterDir(it) : null }, (it.type === 'dir' ? '📁 ' : '📄 ') + it.name),
                      h('span', { className: 'dsw-gh-item-meta' }, it.type === 'dir' ? '目录' : (it.size != null ? Math.round(it.size / 1024) + ' KB' : '')),
                      it.type === 'file' && !isPrivate
                        ? h('a', { className: 'dsw-gh-btn dsw-gh-btn-sm', href: proxyUrl, target: '_blank', rel: 'noreferrer' }, '代理下载')
                        : it.type === 'file'
                          ? h('span', { className: 'dsw-gh-btn dsw-gh-btn-sm dsw-gh-btn-disabled', title: '私有仓库不支持代理下载' }, '代理下载')
                          : null,
                      it.type === 'file' ? h('a', { className: 'dsw-gh-btn dsw-gh-btn-sm', href: dlHref, download: dlHref ? it.name : undefined }, '下载') : null,
                      it.type === 'file' ? h('button', { className: 'dsw-gh-btn dsw-gh-btn-sm', onClick: () => deleteFile(it) }, '删除') : null,
                    )
                  }),
                ),
        ),
        h('div', { className: 'dsw-gh-hint' }, isPrivate ? '当前为私有仓库：代理下载已置灰，请使用「下载」按钮（走 API 认证下载）。' : '文件下载默认走 https://proxy.vvvv.ee 加速；私有文件走 API 直接下载。'),
      )
    }

    slots.inject('conversation.view', () => slots.register(
      { name: 'conversation.view', id: 'gh', order: 40, label: 'GitHub' },
      () => React.createElement(GhView, null),
    ))
  },
}
